        [StructLayout(LayoutKind.Sequential)]
        private struct FullscreenVertex
        {
            public float X;
            public float Y;
            public float Z;
            public float U;
            public float V;

            public FullscreenVertex(float x, float y, float z, float u, float v)
            {
                X = x;
                Y = y;
                Z = z;
                U = u;
                V = v;
            }
        }

        private ID3D11Buffer _quadVertexBuffer;
        private ID3D11InputLayout _quadInputLayout;
        private ID3D11VertexShader _quadVertexShader;
        private ID3D11PixelShader _quadPixelShader;

        ///<summary>
        ///Initializes the fullscreen quad pipeline: vertex buffer, input layout, and shaders.
        ///</summary>
        public void InitializeFullscreenQuad()
        {
            Dlogger.Log(
                LogSubsystems.D3D11,
                LogLevel.Info,
                "D3D11DeviceCore.InitializeFullscreenQuad: (placeholder) " +
                "D3D11DeviceCore: initializing fullscreen quad.");

            DisposeQuadResources();

            //Fullscreen quad as triangle strip in NDC space.
            var vertices = new[]
            {
                new FullscreenVertex(-1.0f,  1.0f, 0.0f, 0.0f, 0.0f),
                new FullscreenVertex( 1.0f,  1.0f, 0.0f, 1.0f, 0.0f),
                new FullscreenVertex(-1.0f, -1.0f, 0.0f, 0.0f, 1.0f),
                new FullscreenVertex( 1.0f, -1.0f, 0.0f, 1.0f, 1.0f)
            };

            var vertexBufferDesc = new BufferDescription(
                (uint)(Marshal.SizeOf<FullscreenVertex>() * vertices.Length),
                BindFlags.VertexBuffer,
                ResourceUsage.Immutable
            );

            var handle = GCHandle.Alloc(vertices, GCHandleType.Pinned);
            try
            {
                var subresourceData = new SubresourceData
                {
                    DataPointer = handle.AddrOfPinnedObject()
                };
                _quadVertexBuffer = Device.CreateBuffer(vertexBufferDesc, subresourceData);
            }
            finally
            {
                handle.Free();
            }

            //Use precompiled shader bytecode from D3D11DeviceCore
            byte[] vsBytecode = QuadVS_Bytecode;
            byte[] psBytecode = QuadPS_Bytecode;

            _quadVertexShader = Device.CreateVertexShader(vsBytecode);
            _quadPixelShader = Device.CreatePixelShader(psBytecode);

            var inputElements = new[]
            {
                new InputElementDescription("POSITION", 0, Format.R32G32B32_Float, 0, 0),
                new InputElementDescription("TEXCOORD", 0, Format.R32G32_Float, 12, 0)
            };

            _quadInputLayout = Device.CreateInputLayout(inputElements, vsBytecode);

            Dlogger.Log(
                LogSubsystems.D3D11,
                LogLevel.Info,
                "D3D11DeviceCore: fullscreen quad initialized.");
        }

        ///<summary>
        ///Draws the fullscreen textured quad using the currently bound SRV and sampler.
        ///</summary>
        public void DrawFullscreenTexturedQuad()
        {
            if (_quadVertexBuffer == null ||
                _quadInputLayout == null ||
                _quadVertexShader == null ||
                _quadPixelShader == null)
            {
                Dlogger.Log(
                    LogSubsystems.D3D11,
                    LogLevel.Info,
                    "D3D11DeviceCore: DrawFullscreenTexturedQuad called before quad initialization.");
                return;
            }

            var context = ImmediateContext;

            uint stride = (uint)Marshal.SizeOf<FullscreenVertex>();
            uint offset = 0;

            context.IASetVertexBuffer(0, _quadVertexBuffer, stride, offset);
            context.IASetInputLayout(_quadInputLayout);
            context.IASetPrimitiveTopology(PrimitiveTopology.TriangleStrip);

            context.VSSetShader(_quadVertexShader);
            context.PSSetShader(_quadPixelShader);

            context.Draw(4, 0);
        }

        ///<summary>
        ///Releases all resources associated with the fullscreen quad pipeline.
        ///</summary>
        private void DisposeQuadResources()
        {
            _quadVertexBuffer?.Dispose();
            _quadVertexBuffer = null;

            _quadInputLayout?.Dispose();
            _quadInputLayout = null;

            _quadVertexShader?.Dispose();
            _quadVertexShader = null;

            _quadPixelShader?.Dispose();
            _quadPixelShader = null;
        }

    }
}
